using Biblia.Application.Interfaces;using Biblia.Application.Interfaces.Repositories;using Biblia.Domain.Entities;using Biblia.Domain.Exceptions;
namespace Biblia.Application.Services;
public sealed class MessageTopicService(IMessageRepository repository):IMessageTopicService{public Task<IReadOnlyList<MessageTopic>> GetTopicsAsync(long messageId,CancellationToken cancellationToken=default)=>repository.GetTopicsAsync(messageId,cancellationToken);public async Task<MessageTopic> SaveAsync(long messageId,long? id,string? title,string? content,CancellationToken cancellationToken=default){if(string.IsNullOrWhiteSpace(title))throw new DomainValidationException("O título do tópico é obrigatório.");var clean=title.Trim();var text=string.IsNullOrWhiteSpace(content)?null:content.Trim();if(id is null or <=0){var next=(await repository.GetTopicsAsync(messageId,cancellationToken)).Count;return await repository.AddTopicAsync(new MessageTopic(0,messageId,clean,text,next),cancellationToken);}var found=(await repository.GetTopicsAsync(messageId,cancellationToken)).SingleOrDefault(x=>x.Id==id)??throw new KeyNotFoundException("Tópico não encontrado.");var updated=found with{Title=clean,Content=text};await repository.UpdateTopicAsync(updated,cancellationToken);return updated;}public Task DeleteAsync(long id,CancellationToken cancellationToken=default)=>repository.DeleteTopicAsync(id,cancellationToken);public async Task MoveAsync(long messageId,IReadOnlyList<MessageTopic> current,long topicId,int direction,CancellationToken cancellationToken=default){var index=current.ToList().FindIndex(x=>x.Id==topicId);var target=index+direction;if(index<0||target<0||target>=current.Count)return;var order=current.Select(x=>x.Id).ToList();(order[index],order[target])=(order[target],order[index]);await repository.ReorderTopicsAsync(messageId,order,cancellationToken);}}
